// Discovery, Spatial Search & Dynamic Comparison (Partition 05-04, SRS §05.04, SR-01 to SR-08, D-05-04-001, D-05-04-002)
func (q *Queries) SearchFleetsSpatial(ctx context.Context, arg SearchFleetsSpatialParams) ([]SearchFleetsSpatialRow, error) {
	rows, err := q.db.Query(ctx, searchFleetsSpatial,
		arg.Longitude,
		arg.Latitude,
		arg.CountryCode,
		arg.RadiusMeters,
		arg.SubcategoryID,
		arg.MinRateMinor,
		arg.MaxRateMinor,
		arg.FuelType,
		arg.OperatorIncluded,
		arg.SelfMoveCapable,
		arg.QueryText,
		arg.StartDate,
		arg.EndDate,
		arg.QueryOffset,
		arg.QueryLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SearchFleetsSpatialRow{}
	for rows.Next() {
		var i SearchFleetsSpatialRow
		if err := rows.Scan(
			&i.ID,
			&i.OwnerID,
			&i.SubcategoryID,
			&i.Make,
			&i.Model,
			&i.ManufactureYear,
			&i.PlateNumber,
			&i.BaselineMeterHours,
			&i.FuelType,
			&i.SelfMoveCapable,
			&i.DailyRateMinor,
			&i.ExcessHourRateMinor,
			&i.MinRentalDays,
			&i.OperatorIncluded,
			&i.Status,
			&i.AddressText,
			&i.CountryCode,
			&i.Latitude,
			&i.Longitude,
			&i.DistanceMeters,
			&i.SubcategoryNameEn,
			&i.SubcategoryNameAm,
			&i.OwnerRating,
			&i.OwnerCompletedRentals,
			&i.OwnerVerified,
			&i.OperatingWeightKg,
			&i.PayloadCapacityKg,
			&i.GrossEnginePowerHp,
			&i.PrimaryPhotoUri,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

